class SnipeRD10Spdr(QCAlgorithm):
    """sp500() vs SPDR holdings on three dates. Examines no returns; not a trial."""

    def initialize(self):
        self.set_start_date(2000, 9, 20)
        self.set_end_date(2007, 10, 5)
        self.set_cash(100000)
        self.sd = SniperData(self)
        self.todo = sorted(SPDR)
        self.add_universe(self.sel)

    @staticmethod
    def n(t):
        return t.replace(".", "").replace("-", "").replace(" ", "").upper()

    def sel(self, fundamental):
        if not self.todo:
            return Universe.UNCHANGED
        d = str(self.time.date())
        nxt = self.todo[0]
        # run on the first selection after the target trading day (selection data = prior close)
        if d <= nxt:
            return Universe.UNCHANGED
        self.todo.pop(0)
        fl = list(fundamental)
        name = {}
        for f in fl:
            try:
                name[f.symbol] = f.company_reference.standard_name
            except Exception:
                name[f.symbol] = "?"
        m = self.sd.sp500(fl)
        got = {self.n(s.value): s for s in m}
        want = set(SPDR[nxt])
        miss = sorted(want - set(got))
        extra = sorted(set(got) - want)
        self.log(f"D {nxt} sel={d} spdr={len(want)} sp500={len(m)} both={len(want & set(got))} missing={len(miss)} extra={len(extra)} listmissing={len(self.sd.sp_missing)}")
        self.log("MISS " + nxt + " " + " ".join(miss))
        self.log("EXTRA " + nxt + " " + " | ".join(f"{t}={name.get(got[t], '?')[:28]}" for t in extra))
        self.log("LISTMISS " + nxt + " " + " ".join(self.sd.sp_missing))
        return []
